    approvals: [{ region: "US", year: 2019, indication: "Advanced urothelial cancer after platinum and PD-1/PD-L1 (accelerated, 18 December 2019; converted to regular approval on 9 July 2021)" },
      { region: "US", year: 2023, indication: "First-line advanced urothelial cancer with pembrolizumab (accelerated on 3 April 2023 for adults ineligible for cisplatin; regular approval for all on 15 December 2023)" }, { region: "US", year: 2025, indication: "With pembrolizumab before and after cystectomy for muscle-invasive bladder cancer in adults ineligible for cisplatin (EV-303; FDA, 21 November 2025)", note: "https://www.fda.gov/drugs/cancer-approvals/fda-approves-pembrolizumab-enfortumab-vedotin-ejfv-muscle-invasive-bladder-cancer" }, { region: "US", year: 2026, indication: "With pembrolizumab before and after cystectomy, extended to all adults with muscle-invasive bladder cancer who are candidates for cystectomy (EV-304; FDA, 10 July 2026)", note: "https://www.fda.gov/drugs/cancer-approvals/fda-approves-pembrolizumab-or-pembrolizumab-and-berahyaluronidase-alfa-pmph-each-enfortumab-vedotin" }, { region: "US", year: 2026, indication: "With durvalumab before cystectomy for muscle-invasive bladder cancer in adults ineligible for or refusing cisplatin, followed by durvalumab alone after surgery (VOLGA; an FDA approval of durvalumab, 13 November 2026; the Padcev label read on 18 November 2026 did not yet list it)", note: "https://www.fda.gov/drugs/cancer-approvals/fda-approves-durvalumab-enfortumab-vedotin-ejfv-muscle-invasive-bladder-cancer" }, { region: "EU", year: 2022, indication: "mUC after platinum + PD-1; 1L with pembrolizumab 2024; with pembrolizumab before and after cystectomy for muscle-invasive bladder cancer 2026 (cisplatin-ineligible June, cisplatin-eligible October)", note: "https://www.ema.europa.eu/en/medicines/human/EPAR/padcev" }, { region: "CN", year: 2024, indication: "Advanced urothelial cancer after platinum and PD-1/PD-L1 (August 2024); with pembrolizumab January 2025, as announced by Astellas", note: "https://www.biospace.com/chinas-national-medical-products-administration-nmpa-approves-padcev-enfortumab-vedotin-for-treatment-of-locally-advanced-or-metastatic-urothelial-cancer" }],
