    targets: ["psma"], technologies: ["radioligand-therapy", "psma-pet"], companies: ["novartis"], cancers: ["prostate", "prostate-mcrpc", "prostate-mhspc"], trials: ["vision", "psmafore", "nct05682443", "nct06894511", "nct06004661"], people: ["louise-emmett"],
