/** Core records merged with dosing, toxicity, access, regulatory events, and mechanism steps from drug-depth.ts. */
export const drugs: DrugInput[] = baseDrugs.map((d) => {
  const depth = drugDepth[d.id];
  if (!depth) return d;
  const merged: DrugInput = { ...d, ...depth };
  // Regulatory events from both files are kept: depth carries the curated timeline, the base record takes feed-applied
  // events (date-stamped FDA approvals). Without this, a depth entry silently hid every event written to the base record.
  if (d.regulatoryEvents?.length && depth.regulatoryEvents) {
    const key = (e: { date: string; region: string; type: string }) => `${e.date}|${e.region}|${e.type}`;
    const seen = new Set(depth.regulatoryEvents.map(key));
    merged.regulatoryEvents = [...depth.regulatoryEvents, ...d.regulatoryEvents.filter((e) => !seen.has(key(e)))];
  }
  return merged;
});
